function saved(message='Alle ændringer er gemt'){if(WriteGuard.uncertain||WriteGuard.needsReview||WriteGuard.loginExpired){failed(WriteGuard.error);return;}SaveStatus.set('saved',message);}
function saving(){if(!WriteGuard.uncertain&&!WriteGuard.needsReview&&!WriteGuard.loginExpired)SaveStatus.set('saving','Gemmer…');}
function failed(message){if(WriteGuard.uncertain){SaveStatus.set('error','Gemning er ikke bekræftet',WriteGuard.error);return;}if(WriteGuard.needsReview){SaveStatus.set('review','Ændringen er gemt · opdatér data før næste ændring',WriteGuard.error);return;}if(WriteGuard.loginExpired||message instanceof RequestError&&message.kind==='login'){SaveStatus.set('error','Login er udløbet · log ind igen.');return;}if(message instanceof RequestError){if(!message.writing)return;if(message.kind==='rejected'){SaveStatus.set('error','Ændringen blev afvist',message);return;}}SaveStatus.set('error','Gemning er ikke bekræftet',message);}
