async function confirmedWrite(path,body,after=async response=>response.json()){
 let accepted=false;try{saving();const response=await api(path,body);accepted=true;const result=await after(response);if(result===false){const error=new RequestError('En nyere redigering er åbnet. Opdater igen, når du er færdig.','response');WriteGuard.requireRefresh(error);toast(error);}else saved();return result;}
 catch(error){if(accepted)WriteGuard.requireRefresh(error);failed(error);throw error;}
}
async function refresh({guard,beforeRender}={}){const fresh=await(await api('/api/state')).json();if(guard&&!guard())return false;state=fresh;if(!selected&&state.cards.length)selected=state.cards[0].id;if(beforeRender)beforeRender();render();return true;}
function mutate(action,data,{close=true,message='Gemt',autosave=false}={}){const epoch=WriteGuard.epoch,payload=JSON.parse(JSON.stringify(data||{})),generation=openDialog.generation;let accepted=false;const work=saveQueue.then(async()=>{WriteGuard.assert(epoch);saving();await api('/api/mutate',{action,data:payload});accepted=true;if(action.startsWith('geo.')||action.startsWith('ignore.')||action.startsWith('address.change.')||action.startsWith('card.restructure.')||['delete','restore','recovery.purge','workflow.undo'].includes(action))await GeoUI.load();await refresh();saved();if(close&&generation===openDialog.generation)closeDialog();const error=el('formError');if(error&&generation===openDialog.generation)error.textContent='';if(!autosave)toast(message);const note=el('formSaved');if(note&&generation===openDialog.generation)note.innerHTML=ui('Gemt automatisk');});saveQueue=work.catch(()=>{});return work.catch(e=>{if(accepted)WriteGuard.requireRefresh(e);failed(e);const err=el('formError');if(err&&generation===openDialog.generation)I18n.errorContent(err,e);else toast(e);throw e;});}
function openDialog(html,language='da'){openDialog.generation=(openDialog.generation||0)+1;frontResizeObserver?.disconnect();DistrictMap.dispose();clearTimeout(autosaveTimer);el('dialog').lang=language==='en'?'en':'da';el('dialog').innerHTML=`<button type="button" class="dialogClose" data-action="close" lang="${I18n.language()}" aria-label="${esc(I18n.text('Luk'))}" title="${esc(I18n.text('Luk'))}">×</button>`+html;el('dialog').showModal();el('dialog').scrollTop=0;I18n.applyShell();}
