function controls(extra=''){return `<div class="toolbar"><input id="search" ${I18n.attribute('aria','Søg kort')} ${I18n.attribute('placeholder','Søg nummer, navn, vej eller adressetype')} value="${esc(query)}"><select id="areaFilter" ${I18n.attribute('aria','Område')}><option value="" data-ui="Alle områder" lang="${I18n.language()}">${esc(I18n.text('Alle områder'))}</option>${state.areas.slice().sort((a,b)=>cmp(a.name,b.name)).map(a=>`<option value="${a.id}" ${area===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select>${extra}</div>`;}
